436	            if (invoice.isVoid()) {
437	                throw new InvoiceRejectedException(number + " is void and takes no payments.");
438	            }
439	            if (invoice.isCreditNote()) {
440	                throw new InvoiceRejectedException(invoice.number() + " is a credit note and takes no payments.");
441	            }
442	            BigDecimal paidSoFar = paid(List.of(invoice)).get(invoice.getId());
443	            BigDecimal due = invoice.amountDue(paidSoFar, taxRate.percent());
444	            if (part.getAmount().compareTo(due) > 0) {
445	                throw new InvoiceRejectedException("The " + currency.format(part.getAmount()) + " for "
446	                        + number + " is more than the " + currency.format(due) + " it has due.");
447	            }
448	            if (invoice.hasPlan() && invoice.isTooSmallPart(part.getAmount(), paidSoFar, taxRate.percent())) {
449	                throw new InvoiceRejectedException("The " + currency.format(part.getAmount()) + " for "
450	                        + number + " is less than the " + currency.format(invoice.earliestUnpaid(paidSoFar, taxRate.percent()))
451	                        + " still unpaid on its earliest unpaid instalment, unless it settles the plan.");
452	            }
453	            if (invoice.isTooSmallPart(part.getAmount(), paidSoFar, taxRate.percent())) {
454	                throw new InvoiceRejectedException("The " + currency.format(part.getAmount()) + " for "
455	                        + number + " is less than " + currency.format(invoice.minimumPart(taxRate.percent()))
456	                        + " (10% of its total), unless it settles the invoice.");
457	            }
458	            if (invoice.getIssueDate() != null && date.isBefore(invoice.getIssueDate())) {
459	                throw new InvoiceRejectedException("The payment date cannot be before the issue date of " + number
460	                        + " (" + invoice.getIssueDate() + ").");
461	            }
462	            spreadOver.add(invoice);
463	        }
464	        if (reference != null && spreadOver.stream().noneMatch(i -> reference.equals(PaymentReference.of(i.getId())))) {
465	            throw new InvoiceRejectedException(PaymentReference.grouped(reference)
466	                    + " is not the reference of any of the invoices being paid.");
467	        }
