491	    private BigDecimal converted(BigDecimal paidAmount, Currency paidIn, Currency clientCurrency, LocalDate date) {
492	        Currency from = paidIn == null ? clientCurrency : paidIn;
493	        requireWhole(from, paidAmount, "The amount");
494	        BigDecimal amount = exchangeRates.convert(paidAmount, from, clientCurrency, date == null ? today.date() : date);
495	        if (amount.signum() <= 0) {
496	            throw new InvoiceRejectedException("The amount is worth nothing once converted into "
